//! 🪆️ Genuine child registrations agree with the actual editor identity and retained command rosters.
use super::*;
#[test]fn genuine_drawing_child_registrations_share_actual_editor_identity_and_admitter(){let fixture:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let dialect:semio_framework_artifact_reference::ArtifactDialect=DRAWING_DIALECT.into();let editor=semio_framework::surface_app_id(&dialect,semio_framework::AppRole::Editor);let rows=[&*DRAWING_CHILD_EDIT_PATH,&*DRAWING_CHILD_EDIT_FILL,&*DRAWING_CHILD_PATCH_LAYER];assert_eq!(editor,fixture["editorId"].as_str().unwrap());for(index,row)in rows.iter().enumerate(){assert_eq!(row.identity.editor_id,editor);assert_eq!(row.identity.command_id,fixture["commands"][index].as_str().unwrap());assert!(crate::bounded_commands::DRAWING_BOUNDED_TOOL_IDS.contains(&row.identity.command_id)||crate::bounded_commands::DRAWING_PATH_TOOL_IDS.contains(&row.identity.command_id));assert_eq!(row.identity.artifact_kind,dialect.artifact_kind);assert_eq!(row.identity.standard,dialect.standard);assert_eq!(row.identity.subset,dialect.subset);assert!(std::ptr::eq(row.admission,&DRAWING_ADMITTER));assert!(std::ptr::eq(row.vector,&DRAWING_VECTOR_SOURCE));}}
